$ErrorActionPreference='Stop';$id=[guid]::NewGuid().ToString('N');$run=Join-Path $PSScriptRoot ('TestRuns\grid-resequence-'+$id);$source=Join-Path $PSScriptRoot 'Fixtures\GridResequenceEmpty.rvt';$before=(Get-FileHash $source -Algorithm SHA256).Hash
try{$r=& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'Prepare-GridResequenceQaRun.ps1') -RunId $id|ConvertFrom-Json;$p=Get-Content $r.SidecarPath -Raw|ConvertFrom-Json;$expected=@('1','2','3','3.2','4','A','A.1','B','C');$declared=@($p.requiredGridNames|ForEach-Object{[string]$_});if($r.FixtureId -cne 'GridResequenceEmpty' -or $p.fixtureId -cne 'GridResequenceEmpty' -or $p.sourceSha256 -ine $before -or (Get-FileHash $r.ModelPath -Algorithm SHA256).Hash -ine $before -or (($declared|Sort-Object)-join '|') -cne (($expected|Sort-Object)-join '|') -or (($p.layout.verticalLeftToRight)-join '|') -cne 'B|A.1|C|A' -or (($p.layout.horizontalBottomToTop)-join '|') -cne '2|3.2|1|4|3'){throw 'Fixture preparation identity, grid set, or layout mismatch.'};if((Get-FileHash $source -Algorithm SHA256).Hash -ine $before){throw 'Repository fixture changed.'};'Grid Resequence fixture preparation checks passed: 4'}finally{if(Test-Path $run){Remove-Item $run -Recurse -Force}}
